-- Phone call log (docs/designs/call-log/call-log.md, WF-X16, R-084 standalone): calls not tied to an enquiry, per centre,
-- append-only (DD-3); read on enquiry.view, logged on enquiry.manage (DD-2). The DDL down to the foreign keys was
-- generated by prisma migrate diff.

-- CreateTable
CREATE TABLE "app"."call_log" (
    "id" BIGSERIAL NOT NULL,
    "centre_id" INTEGER NOT NULL,
    "phone" TEXT NOT NULL,
    "name" TEXT,
    "called_on" DATE NOT NULL,
    "call_type" TEXT NOT NULL,
    "duration_min" INTEGER,
    "description" TEXT,
    "note" TEXT,
    "next_follow_up_on" DATE,
    "tele_caller" UUID,
    "by_user" UUID NOT NULL,
    "at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "call_log_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "call_log_centre_id_called_on_id_idx" ON "app"."call_log"("centre_id", "called_on", "id");

-- AddForeignKey
ALTER TABLE "app"."call_log" ADD CONSTRAINT "call_log_centre_id_fkey" FOREIGN KEY ("centre_id") REFERENCES "app"."centre"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "app"."call_log" ADD CONSTRAINT "call_log_tele_caller_fkey" FOREIGN KEY ("tele_caller") REFERENCES "app"."app_user"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "app"."call_log" ADD CONSTRAINT "call_log_by_user_fkey" FOREIGN KEY ("by_user") REFERENCES "app"."app_user"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- ---------- Named checks (mirrored in src/server/call-log.ts); the constants are 0018's, copied ----------
do $$
declare
  ws constant text := '[\t\n\v\f\r    -     　﻿]';
  ctl constant text := '[\u0001-\u001f\u007f]';
  ctl_address constant text := '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]'; -- tab, newline, carriage return allowed
  c text; n int;
begin
  for c, n in select * from (values ('name', 100), ('description', 1000), ('note', 1000)) v(c, n) loop
    execute format('alter table app.call_log add constraint %I check (%I !~ %L and %I !~ %L and %I !~ %L and char_length(%I) between 1 and %s)',
      'call_log_' || c || '_check', c, '^' || ws, c, ws || '$', c, case when c = 'name' then ctl else ctl_address end, c, n);
  end loop;
end $$;
alter table app.call_log add constraint call_log_phone_check check (phone ~ '^[0-9]{10}$');
alter table app.call_log add constraint call_log_call_type_check check (call_type in ('CALL_IN', 'CALL_OUT'));
alter table app.call_log add constraint call_log_duration_min_check check (duration_min between 0 and 600); -- PMC
alter table app.call_log add constraint call_log_follow_up_check check (next_follow_up_on >= called_on);

-- ---------- Who and when come from the database; the log never changes (as enquiry_followup, 0018) ----------
create function app.call_log_guard() returns trigger
language plpgsql security invoker set search_path = pg_catalog, app
as $$
begin
  new.by_user := coalesce(app.session_user_id(), new.by_user);
  new.at := now();
  return new;
end $$;
create trigger call_log_guard before insert on app.call_log for each row execute function app.call_log_guard();
create trigger call_log_no_update_delete before update or delete on app.call_log
  for each row execute function app.ticket_immutable();
create trigger call_log_no_truncate before truncate on app.call_log
  for each statement execute function app.ticket_immutable();

-- ---------- RLS: enquiry.view reads, enquiry.manage logs; update and delete never (T-RLS-002's four commands) ----------
alter table app.call_log enable row level security;
alter table app.call_log force row level security;
create policy call_log_select on app.call_log for select using (centre_id = any ((select app.scoped_centre_ids('enquiry.view'))::int[]));
create policy call_log_insert on app.call_log for insert with check (centre_id = any ((select app.scoped_centre_ids('enquiry.manage'))::int[]));
create policy call_log_update on app.call_log for update using (false);
create policy call_log_delete on app.call_log for delete using (false);

-- ---------- Grants: the id is reserved first; who and when are the guard's ----------
grant select, insert (id, centre_id, phone, name, called_on, call_type, duration_min, description, note, next_follow_up_on, tele_caller)
  on app.call_log to gems_app;
grant usage on sequence app.call_log_id_seq to gems_app;
